<?php declare(strict_types=1);
namespace App\Services;
use App\Core\Database; use App\Repositories\{LiquidityPredictionMarketRepository,LiquidityPredictionOptionRepository,LiquidityPredictionBetRepository,LiquidityPredictionResolutionRepository,LiquidityPredictionPayoutRepository,LiquiditySessionRepository,LiquidityTeamRepository,LiquidityEventRepository}; use DomainException; use PDO;
final class LiquidityPredictionMarketService{private PDO $pdo; private LiquidityPredictionMarketRepository $markets; private LiquidityPredictionOptionRepository $options; private LiquidityPredictionBetRepository $bets; private LiquidityPredictionResolutionRepository $resolutions; private LiquidityPredictionPayoutRepository $payouts; private LiquiditySessionRepository $sessions; private LiquidityTeamRepository $teams; private LiquidityEventRepository $events;
public function __construct(?PDO $pdo=null){$this->pdo=$pdo??Database::connection();$this->markets=new LiquidityPredictionMarketRepository($this->pdo);$this->options=new LiquidityPredictionOptionRepository($this->pdo);$this->bets=new LiquidityPredictionBetRepository($this->pdo);$this->resolutions=new LiquidityPredictionResolutionRepository($this->pdo);$this->payouts=new LiquidityPredictionPayoutRepository($this->pdo);$this->sessions=new LiquiditySessionRepository($this->pdo);$this->teams=new LiquidityTeamRepository($this->pdo);$this->events=new LiquidityEventRepository($this->pdo);} 
public function createMarket($sessionId,$question,$description,$options,$closesRound,$createdBy=null){if(trim((string)$question)==='')throw new DomainException('Pergunta obrigatória.');$options=array_values(array_filter(array_map(fn($o)=>trim((string)$o),$options)));if(count($options)<2)throw new DomainException('Informe ao menos 2 opções.');$this->pdo->beginTransaction();try{$marketId=$this->markets->create($sessionId,$question,$description,'multiple_choice',$closesRound,$createdBy);$this->options->createMany($marketId,$options);$this->recalculateProbabilities($marketId);$this->events->create((int)$sessionId,(int)($this->sessions->findById((int)$sessionId)['current_round']??1),null,'prediction_market_created','Professor criou mercado: '.$question,0,0,0,0);$this->pdo->commit();return $this->getMarketDetail($marketId);}catch(\Throwable $e){if($this->pdo->inTransaction())$this->pdo->rollBack();throw $e;}}
public function placeBet($sessionId,$teamId,$marketId,$optionId,$amount){$amount=(float)$amount; if($amount<=0)throw new DomainException('Valor inválido.');$session=$this->sessions->findById((int)$sessionId);$team=$this->teams->findById((int)$teamId);$market=$this->markets->findById((int)$marketId);if(!$session||$session['status']!=='active')throw new DomainException('Sessão inativa.');if(!$team||(int)$team['session_id']!==(int)$sessionId)throw new DomainException('Equipe inválida.');if(!$market||(int)$market['session_id']!==(int)$sessionId||$market['status']!=='open')throw new DomainException('Mercado não está aberto.');if(!$this->markets->optionBelongsToMarket((int)$optionId,(int)$marketId))throw new DomainException('Opção inválida.');if((float)$team['cash_balance']<$amount)throw new DomainException('Caixa insuficiente.');
$this->pdo->beginTransaction();try{$this->teams->decreaseCash((int)$teamId,$amount);$this->bets->create((int)$marketId,(int)$optionId,(int)$sessionId,(int)$teamId,$amount);$this->options->incrementWeight((int)$optionId,$amount);$this->recalculateProbabilities((int)$marketId);$op=$this->options->findById((int)$optionId);$this->events->create((int)$sessionId,(int)$session['current_round'],(int)$teamId,'prediction_bet_placed','Equipe '.$team['name'].' apostou R$ '.number_format($amount,2,',','.').' em '.$op['label'].' no mercado: '.$market['question'],-$amount,0,0,0);$this->pdo->commit();}catch(\Throwable $e){if($this->pdo->inTransaction())$this->pdo->rollBack();throw $e;}}
public function recalculateProbabilities($marketId){$opts=$this->options->getByMarketId((int)$marketId);$total=array_sum(array_map(fn($o)=>(float)$o['weight_value'],$opts));foreach($opts as $o){$this->options->updateProbability((int)$o['id'],$total>0?((float)$o['weight_value']/$total):0.0);}}
public function closeMarket($marketId,$actorUserId=null){$m=$this->markets->findById((int)$marketId);if(!$m||$m['status']!=='open')throw new DomainException('Mercado não pode ser fechado.');$this->markets->setStatus((int)$marketId,'closed');$this->events->create((int)$m['session_id'],(int)($this->sessions->findById((int)$m['session_id'])['current_round']??1),null,'prediction_market_closed','Mercado preditivo fechado: '.$m['question'],0,0,0,0);} 
public function resolveMarket($marketId,$winningOptionId,$actorUserId=null,$notes=null){$m=$this->markets->findById((int)$marketId);if(!$m||!in_array($m['status'],['open','closed'],true))throw new DomainException('Mercado não pode ser resolvido.');if($this->resolutions->existsForMarket((int)$marketId))throw new DomainException('Mercado já resolvido.');if(!$this->markets->optionBelongsToMarket((int)$winningOptionId,(int)$marketId))throw new DomainException('Opção inválida.');$this->pdo->beginTransaction();try{$this->resolutions->create((int)$marketId,(int)$winningOptionId,$actorUserId,$notes);$this->markets->setResolvedOption((int)$marketId,(int)$winningOptionId);$this->markets->setStatus((int)$marketId,'resolved');$this->executePayouts((int)$marketId,(int)$winningOptionId);$op=$this->options->findById((int)$winningOptionId);$this->events->create((int)$m['session_id'],(int)($this->sessions->findById((int)$m['session_id'])['current_round']??1),null,'prediction_market_resolved','Mercado preditivo resolvido: '.$m['question'].'. Resultado: '.$op['label'],0,0,0,0);$this->pdo->commit();}catch(\Throwable $e){if($this->pdo->inTransaction())$this->pdo->rollBack();throw $e;}}
public function executePayouts($marketId,$winningOptionId){foreach($this->bets->getWinningBets((int)$marketId,(int)$winningOptionId) as $b){if($this->payouts->existsForBet((int)$marketId,(int)$b['id']))continue;$gross=(float)$b['amount']*2;$this->payouts->create((int)$marketId,(int)$b['id'],(int)$b['session_id'],(int)$b['team_id'],(int)$b['option_id'],$gross,0,$gross);$this->teams->increaseCash((int)$b['team_id'],$gross);$this->events->create((int)$b['session_id'],(int)($this->sessions->findById((int)$b['session_id'])['current_round']??1),(int)$b['team_id'],'prediction_payout_executed','Payoff preditivo executado para equipe #'.$b['team_id'].' no mercado #'.$marketId, $gross,0,0,0);}}
public function getMarketsForSession($sid){$all=$this->markets->getBySessionId((int)$sid);foreach($all as &$m){$m['options']=$this->options->getByMarketId((int)$m['id']);}return $all;} public function getMarketsForTeamDashboard($sid){return $this->getMarketsForSession((int)$sid);} public function getMarketDetail($id){$m=$this->markets->findById((int)$id);if(!$m)return null;$m['options']=$this->options->getByMarketId((int)$id);$m['bets']=$this->bets->getByMarketId((int)$id);$m['resolution']=$this->resolutions->findByMarketId((int)$id);$m['payouts']=$this->payouts->getByMarketId((int)$id);return $m;}}
